svg.script:
(function () {
  function retrigger(el) {
    if (!el) return;
    el.classList.remove('student-react');
    void el.getBoundingClientRect();
    el.classList.add('student-react');
    setTimeout(function () {
      el.classList.remove('student-react');
    }, 500);
  }

  document.querySelectorAll('.student-hotspot').forEach(function (spot) {
    spot.addEventListener('pointerdown', function (ev) {
      ev.preventDefault();
      retrigger(document.getElementById(spot.getAttribute('data-target')));
    });
  });
})();
